<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { usuariosApi } from '../api/resources'; import { errorMessage } from '../api/client'; import type { PerfilUsuario } from '../types'
const router = useRouter(); const nome = ref(''); const email = ref(''); const senha = ref(''); const perfil = ref<PerfilUsuario>('ADVOGADO'); const error = ref(''); const loading = ref(false)
async function submit() { loading.value = true; error.value = ''; try { await usuariosApi.criar({ nome: nome.value, email: email.value, senha: senha.value, perfil: perfil.value }); router.push('/usuarios') } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
</script>
<template><section class="page narrow"><header class="page-header"><div><p class="eyebrow">Administração</p><h1>Novo usuário</h1></div></header><form class="card form" @submit.prevent="submit"><p v-if="error" class="alert error">{{ error }}</p><label>Nome<input v-model.trim="nome" required maxlength="150" /></label><label>E-mail<input v-model.trim="email" type="email" required /></label><label>Senha<input v-model="senha" type="password" required minlength="8" maxlength="100" /></label><label>Perfil<select v-model="perfil"><option value="ADVOGADO">Advogado</option><option value="ADMINISTRADOR">Administrador</option><option value="CLIENTE">Cliente</option></select></label><button class="primary" :disabled="loading">{{ loading ? 'Criando...' : 'Criar usuário' }}</button></form></section></template>